using sv_651a6b069f9d44929f95a30569947666.Models;

namespace sv_651a6b069f9d44929f95a30569947666.Services;

public sealed class RecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomato sauce.", 30),
            new(2, "Risotto alla Milanese", "Creamy saffron-infused risotto from Milan, finished with butter and Parmigiano-Reggiano.", 45),
            new(3, "Tiramisu", "Layered dessert of espresso-soaked ladyfingers and mascarpone cream dusted with cocoa.", 40),
            new(4, "Pasta Carbonara", "Roman pasta with guanciale, egg yolks, Pecorino Romano, and black pepper.", 25),
        },
        [2] = new List<Recipe>
        {
            new(5, "Pad Thai", "Stir-fried rice noodles with shrimp, tofu, bean sprouts, peanuts, and tamarind sauce.", 35),
            new(6, "Green Curry", "Aromatic coconut-milk curry with Thai basil, bamboo shoots, and green chili paste.", 40),
            new(7, "Tom Yum Soup", "Hot and sour soup with lemongrass, galangal, kaffir lime leaves, and prawns.", 25),
        },
        [3] = new List<Recipe>
        {
            new(8, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion on corn tortillas.", 50),
            new(9, "Guacamole", "Fresh avocado dip with lime juice, cilantro, jalapeño, tomato, and onion.", 10),
            new(10, "Chicken Enchiladas", "Corn tortillas filled with shredded chicken, smothered in red chili sauce and cheese.", 45),
            new(11, "Churros", "Fried dough pastries coated in cinnamon sugar, served with chocolate dipping sauce.", 30),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        return RecipesByCuisine.TryGetValue(cuisineId, out var recipes)
            ? new List<Recipe>(recipes)
            : new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_651a6b069f9d44929f95a30569947666.Models
@using sv_651a6b069f9d44929f95a30569947666.Services
@inject RecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<div class="mb-3">
    <label class="form-label fw-semibold">Sort by:</label>
    <div class="btn-group ms-2" role="group">
        <a href="@GetSortUrl("newest")"
           class="btn btn-sm @(Sort == "popular" ? "btn-outline-primary" : "btn-primary")">
            Newest
        </a>
        <a href="@GetSortUrl("popular")"
           class="btn btn-sm @(Sort == "popular" ? "btn-primary" : "btn-outline-primary")">
            Popular
        </a>
    </div>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-auto">@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="d-flex align-items-center gap-2 mb-3 text-muted small">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <span>Refreshing…</span>
        </div>
    }

    @if (_sortedRecipes.Count == 0)
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-3">
            @foreach (var recipe in _sortedRecipes)
            {
                <div class="col">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                        </div>
                        <div class="card-footer text-muted">
                            🕐 @recipe.PrepTimeMinutes min
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private List<Recipe> _sortedRecipes = new();
    private bool _isRefreshing;
    private string? _errorMessage;

    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            _loadedCuisineId = CuisineId;
            _ = LoadRecipesAsync();
        }
        else if (_recipes is not null)
        {
            _sortedRecipes = ApplySort(_recipes);
        }

        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        _loadCts?.Cancel();
        _loadCts?.Dispose();

        using var cts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        _loadCts = cts;

        _errorMessage = null;
        _isRefreshing = _recipes is not null;
        StateHasChanged();

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = result;
            _sortedRecipes = ApplySort(_recipes);
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (_disposeCts.IsCancellationRequested)
        {
            // Component is being disposed — do nothing.
        }
        catch (OperationCanceledException)
        {
            // Superseded by a newer load — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
            _isRefreshing = false;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
            _isRefreshing = false;
        }
    }

    private List<Recipe> ApplySort(List<Recipe> recipes) =>
        string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : recipes.OrderByDescending(r => r.Id).ToList();

    private void Retry() => _ = LoadRecipesAsync();

    private string GetSortUrl(string sort) =>
        Navigation.GetUriWithQueryParameter("sort", sort);

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

